explain select a.ticker, e.short_name, max(a.date) max_quarter, max(b.date) max_pnl, max(c.date) max_balancesheet, max(d.date) max_cashflow from stock_quarter a, stock_pnl b, stock_balancesheet c, stock_cashflow d, stock_universe e
where a.ticker = b.ticker AND b.ticker = c.ticker AND c.ticker = d.ticker AND d.ticker = e.ticker AND
e.is_bse500 = 1 or e.is_nse500 = 1
group by ticker;
*/
-- ---------------------- 
select a.ticker, b.short_name, max(date) from stock_quarter a, stock_universe b where a.ticker = b.ticker group by a.ticker order by b.marketcap desc;
select a.ticker, b.short_name, max(date) from stock_pnl a, stock_universe b where a.ticker = b.ticker group by a.ticker order by b.marketcap desc;
select a.ticker, b.short_name, max(date) from stock_balancesheet a, stock_universe b where a.ticker = b.ticker group by a.ticker order by b.marketcap desc;
select a.ticker, b.short_name, max(date) from stock_cashflow a, stock_universe b where a.ticker = b.ticker group by a.ticker order by b.marketcap desc;

